:root {
  color-scheme: light;
  --page: #e8edf1;
  --shell: #282a2f;
  --shell-top: #3b3e45;
  --screen: #bdd9a6;
  --screen-ink: #172312;
  --key: #f6f7f4;
  --key-edge: #b7bdba;
  --key-ink: #1f2427;
  --accent: #2f72cc;
  --op: #e58d2e;
  --op-edge: #9b5514;
  --green: #279a77;
  --red: #ca514c;
  --radius: 8px;
}

@counter-style calc-sign {
  system: fixed 0;
  symbols: "" "-";
  suffix: "";
}

* { box-sizing: border-box; }
html, body { min-height: 100%; }
body {
  margin: 0;
  background: linear-gradient(135deg, rgb(255 255 255 / 70%), rgb(207 216 222 / 76%)), var(--page);
  color: var(--key-ink);
  font: 500 16px/1.4 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
button, input, label { font: inherit; }
.app { min-height: 100vh; display: grid; place-items: center; padding: clamp(0.85rem, 3vw, 2rem); }
